import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';

// Reproduce the exact real CSS generated by the native Milky backend,
// including the GNOME Dark Style path. Do not accept a mock CSS string:
const root = new URL('../gnome-shell/vliq@wonderer.tech/', import.meta.url);
const [source, paintSource] = await Promise.all([
    'nativeCssIntegration.js', 'milkyPaint.js',
].map(x => readFile(new URL(x, root), 'utf8')));
const paint = new Function(paintSource.replace(/^export /gm, '') +
    '\nreturn {milkyPaintTokens, buildMilkyAppearanceCss};')();
const start = source.indexOf("    _milkyCss(state, grainUri = '') {");
const end = source.indexOf('\n    _refreshMilkyAppearance() {', start);
assert.ok(start >= 0 && end > start,
    'production NativeCssIntegration._milkyCss is present');
const actual = new Function('milkyPaintTokens', 'buildMilkyAppearanceCss',
    'return ({' + source.slice(start, end) + '})._milkyCss;')(
    paint.milkyPaintTokens, paint.buildMilkyAppearanceCss);

for (const opacity of [0.24, 0.75]) {
    const css = actual.call({}, {
        milky: true, milkyOpacity: opacity,
        milkyWhiteness: 1, milkyBorder: 0.5,
    });
    assert.match(css, /background-color: rgba\(255,255,255,1\.000\) !important/,
        'white +100 is fully opaque on native card');
    // A more-specific GNOME Dark Style selector used to unconditionally
    // override every Milky popup with opaque CHARCOAL, making all 4 sliders
    // visually ineffective while Dark Style is selected.
    assert.doesNotMatch(css,
        /\.vliq-native-css\.vliq-global-milky\.vliq-native-css-dark\s+\.popup-menu-content\s*\{[^}]*background-color:\s*rgba\(29,\s*31,\s*35/,
        'Milky popup material must honor its controls even with Dark Style enabled');
    assert.match(css,
        /\.vliq-native-css\.vliq-global-milky\s+\.popup-menu-content\s*\{[^}]*background-color:\s*rgba\(255,255,255,1\.000\)/,
        'Milky card must remain white under system Dark Style');
    assert.match(css,
        /\.vliq-bottom-taskbar\.vliq-system-dark-taskbar\s*\{[^}]*rgba\(29,31,35,0\.98\)/,
        'Bottom-only dark bar must continue to obey the requested native Dark Style');
}
console.log('Milky native Dark Style: popup color/opacity live; only Bottom Taskbar remains dark PASS.');
